function FloatingParticle({ delay, duration, startX, startY }: { delay: number; duration: number; startX: number; startY: number }) {
  return (
    <motion.div
      className="absolute w-1 h-1 rounded-full bg-primary/40"
      style={{ left: `${startX}%`, top: `${startY}%` }}
      animate={{
        y: [0, -100, -200],
        x: [0, Math.random() * 40 - 20, Math.random() * 60 - 30],
        opacity: [0, 1, 0],
        scale: [0, 1.5, 0],
      }}
      transition={{
        duration,
        delay,
        repeat: Infinity,
        ease: "easeOut",
      }}
    />
  );
}

export default function Login() {
  const [isLoading, setIsLoading] = useState<"google" | "discord" | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [particles, setParticles] = useState<Array<{ id: number; delay: number; duration: number; startX: number; startY: number }>>([]);
  const oauthTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const { oauthDeepLinkReceived, oauthError } = useAuthStore();

  const clearOAuthTimeout = useCallback(() => {
    if (oauthTimeoutRef.current) {
      clearTimeout(oauthTimeoutRef.current);
      oauthTimeoutRef.current = null;
      console.log('[Login] OAuth timeout cleared');
    }
  }, []);

  useEffect(() => {
    if (oauthDeepLinkReceived) {
      console.log('[Login] Deep link received — clearing timeout and loading state');
      clearOAuthTimeout();
      if (isLoading) {
        setIsLoading(null);
        setError(null);
      }
      useAuthStore.getState().setOauthDeepLinkReceived(false);
    }
  }, [oauthDeepLinkReceived, isLoading, clearOAuthTimeout]);

  useEffect(() => {
    if (oauthError) {
      console.log('[Login] OAuth error from store:', oauthError);
      clearOAuthTimeout();
      setIsLoading(null);
      setError(oauthError);
      useAuthStore.getState().setOauthError(null);
    }
  }, [oauthError, clearOAuthTimeout]);

  useEffect(() => {
    return () => {
      clearOAuthTimeout();
    };
  }, [clearOAuthTimeout]);

  useEffect(() => {
    const newParticles = Array.from({ length: 30 }, (_, i) => ({
      id: i,
      delay: Math.random() * 5,
      duration: 3 + Math.random() * 4,
      startX: Math.random() * 100,
      startY: 50 + Math.random() * 50,
    }));
    setParticles(newParticles);
  }, []);

  const handleLogin = async (provider: "google" | "discord") => {
    setIsLoading(provider);
    setError(null);
    useAuthStore.getState().setOauthDeepLinkReceived(false);

    const api = (window as any).electronAPI;
    const isElectron = api?.isElectron && api?.openExternal;

    if (isElectron) {
      const authUrl = `${AUTH_DOMAIN}/auth/${provider}?source=electron`;
      console.log('[Login] Opening external auth URL:', authUrl);
      try {
        await api.openExternal(authUrl);

        clearOAuthTimeout();
        oauthTimeoutRef.current = setTimeout(() => {
          console.warn('[Login] OAuth timeout — no deep link received within', OAUTH_TIMEOUT_MS, 'ms');
          setIsLoading(null);
          setError("Login cancelled or timed out");
          oauthTimeoutRef.current = null;
        }, OAUTH_TIMEOUT_MS);
        console.log(`[Login] OAuth timeout started (${OAUTH_TIMEOUT_MS}ms)`);
      } catch (err) {
        console.error('[Login] Failed to open auth URL:', err);
        setError("Failed to open browser. Please try again.");
        setIsLoading(null);
      }
    } else {
      setError("This app must be run inside the SwitchControl desktop app.");
      setIsLoading(null);
      return;
    }
  };

  return (
    <div className="fixed inset-0 bg-[#0a0a0f] overflow-hidden flex items-center justify-center">
      <motion.div 
        className="absolute inset-0 pointer-events-none"
        animate={{
          background: [
            "radial-gradient(ellipse 80% 50% at 50% 50%, rgba(139, 92, 246, 0.15) 0%, transparent 50%)",
            "radial-gradient(ellipse 60% 40% at 45% 45%, rgba(139, 92, 246, 0.2) 0%, transparent 50%)",
            "radial-gradient(ellipse 80% 50% at 55% 55%, rgba(139, 92, 246, 0.15) 0%, transparent 50%)",
          ]
        }}
        transition={{ duration: 8, repeat: Infinity, ease: "easeInOut" }}
      />

      <motion.div
        className="absolute inset-0 pointer-events-none"
        style={{
          background: "radial-gradient(circle at 30% 20%, rgba(236, 72, 153, 0.1) 0%, transparent 40%)",
        }}
        animate={{
          opacity: [0.3, 0.6, 0.3],
        }}
        transition={{ duration: 5, repeat: Infinity, ease: "easeInOut" }}
      />

      <motion.div
        className="absolute inset-0 pointer-events-none"
        style={{
          background: "radial-gradient(circle at 70% 80%, rgba(59, 130, 246, 0.08) 0%, transparent 40%)",
        }}
        animate={{
          opacity: [0.2, 0.5, 0.2],
        }}
        transition={{ duration: 7, repeat: Infinity, ease: "easeInOut", delay: 2 }}
      />

      <div 
        className="absolute inset-0 overflow-hidden pointer-events-none" 
        style={{ transform: 'rotate(-12deg) scale(1.4)' }}
      >
        <motion.div 
          className="absolute inset-0" 
          style={{ opacity: 0.12 }}
          animate={{ y: [0, -20, 0] }}
          transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
        >
          <svg className="w-full h-full" xmlns="http://www.w3.org/2000/svg">
            <defs>
              <pattern id="loginTopo" x="0" y="0" width="200" height="150" patternUnits="userSpaceOnUse">
                <path d="M0 50 Q50 25 100 50 T200 50" fill="none" stroke="hsl(270 50% 55%)" strokeWidth="0.8" opacity="0.6"/>
                <path d="M0 100 Q50 75 100 100 T200 100" fill="none" stroke="hsl(280 45% 60%)" strokeWidth="0.6" opacity="0.5"/>
                <path d="M0 25 Q50 0 100 25 T200 25" fill="none" stroke="hsl(260 55% 50%)" strokeWidth="0.5" opacity="0.4"/>
                <path d="M0 125 Q50 100 100 125 T200 125" fill="none" stroke="hsl(270 50% 45%)" strokeWidth="0.4" opacity="0.3"/>
              </pattern>
            </defs>
            <rect width="300%" height="300%" x="-100%" y="-100%" fill="url(#loginTopo)"/>
          </svg>
        </motion.div>
      </div>

      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        {particles.map((p) => (
          <FloatingParticle key={p.id} {...p} />
        ))}
      </div>

      <div className="absolute inset-0 bg-gradient-to-t from-[#0a0a0f] via-transparent to-[#0a0a0f]/80 pointer-events-none" />
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_0%,#0a0a0f_70%)] pointer-events-none" />

