import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Loader2, RefreshCw, CheckCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { refreshEntitlements } from '@/lib/auth-store';

interface PendingActivationModalProps {
  show: boolean;
  onUpgradeDetected: () => void;
  onDismiss: () => void;
}

export function PendingActivationModal({ show, onUpgradeDetected, onDismiss }: PendingActivationModalProps) {
  const [status, setStatus] = useState<'syncing' | 'retrying' | 'failed'>('syncing');
  const [countdown, setCountdown] = useState(30);
  const [retryCount, setRetryCount] = useState(0);

  const checkPremium = useCallback(async () => {
    console.log('[PendingActivation] Checking premium status...');
    const result = await refreshEntitlements();

    if (result.user?.isPremium) {
      console.log('[PendingActivation] Premium detected!');
      setStatus('syncing');
      onUpgradeDetected();
      return true;
    }
    return false;
  }, [onUpgradeDetected]);

  useEffect(() => {
    if (!show) {
      setStatus('syncing');
      setCountdown(30);
      setRetryCount(0);
      return;
    }

    let interval: NodeJS.Timeout;
    let checkInterval: NodeJS.Timeout;

    const startChecking = async () => {
      const found = await checkPremium();
      if (found) return;

      interval = setInterval(() => {
        setCountdown(prev => {
          if (prev <= 1) {
            clearInterval(interval);
            clearInterval(checkInterval);
            setStatus('failed');
            return 0;
          }
          return prev - 1;
        });
      }, 1000);

      checkInterval = setInterval(async () => {
        setRetryCount(prev => prev + 1);
        const found = await checkPremium();
        if (found) {
          clearInterval(interval);
          clearInterval(checkInterval);
        }
      }, 3000);
    };

    startChecking();

    return () => {
      clearInterval(interval);
      clearInterval(checkInterval);
    };
  }, [show, checkPremium]);

  const handleRetry = async () => {
    setStatus('retrying');
    setCountdown(30);
    setRetryCount(0);

    const found = await checkPremium();
    if (!found) {
      setStatus('syncing');
    }
  };

  if (!show) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"
      >
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
          className="relative w-full max-w-sm bg-card/95 backdrop-blur-xl border border-purple-500/30 rounded-2xl p-6 shadow-2xl"
        >
          <div className="text-center space-y-4">
            {status === 'syncing' && (
              <>
                <motion.div
                  className="size-16 mx-auto rounded-full bg-purple-500/20 flex items-center justify-center"
                  animate={{ 
                    boxShadow: [
                      '0 0 20px rgba(139, 92, 246, 0.3)',
                      '0 0 40px rgba(139, 92, 246, 0.5)',
                      '0 0 20px rgba(139, 92, 246, 0.3)',
                    ]
                  }}
                  transition={{ duration: 2, repeat: Infinity }}
                >
                  <Loader2 className="size-8 text-purple-400 animate-spin" />
                </motion.div>
                <div>
                  <h3 className="text-lg font-semibold text-white">Activating Premium</h3>
                  <p className="text-sm text-muted-foreground mt-2">
                    Syncing your purchase... ({countdown}s)
                  </p>
                  <p className="text-xs text-muted-foreground/60 mt-1">
                    Attempt {retryCount + 1}
                  </p>
                </div>
                <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden">
                  <motion.div
                    className="h-full bg-gradient-to-r from-purple-500 to-pink-500"
                    initial={{ width: '100%' }}
                    animate={{ width: `${(countdown / 30) * 100}%` }}
                    transition={{ duration: 0.5 }}
                  />
                </div>
              </>
            )}

            {status === 'retrying' && (
              <>
                <div className="size-16 mx-auto rounded-full bg-purple-500/20 flex items-center justify-center">
                  <RefreshCw className="size-8 text-purple-400 animate-spin" />
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-white">Retrying...</h3>
                  <p className="text-sm text-muted-foreground mt-2">
                    Checking for premium status
                  </p>
                </div>
              </>
            )}

            {status === 'failed' && (
              <>
                <div className="size-16 mx-auto rounded-full bg-yellow-500/20 flex items-center justify-center">
                  <RefreshCw className="size-8 text-yellow-400" />
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-white">Still Syncing</h3>
                  <p className="text-sm text-muted-foreground mt-2">
                    Your payment is being processed. This usually takes a moment.
                  </p>
                </div>
                <div className="flex flex-col gap-2 pt-2">
                  <Button 
                    onClick={handleRetry}
                    className="w-full bg-purple-500 hover:bg-purple-600"
                  >
                    <RefreshCw className="size-4 mr-2" />
                    Retry Now
                  </Button>
                  <Button 
                    variant="ghost"
                    onClick={onDismiss}
                    className="w-full text-muted-foreground"
                  >
                    Dismiss (Restart App Later)
                  </Button>
                </div>
              </>
            )}
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}

server/auth/google.ts.content:
import passport from "passport";
import { Strategy as GoogleStrategy } from "passport-google-oauth20";
import session from "express-session";
import connectPg from "connect-pg-simple";
import MemoryStore from "memorystore";
import type { Express, RequestHandler } from "express";
import { db, isNoDbMode } from "../db";
import { users } from "@shared/models/auth";
import { eq } from "drizzle-orm";
import { storage } from "../storage";
import { signJwt, verifyJwt } from "../lib/jwt";

declare global {
  namespace Express {
    interface User {
      id: string;
      email: string | null;
      firstName: string | null;
      lastName: string | null;
      profileImageUrl: string | null;
      isPremium: boolean;
    }
  }
}

async function findOrCreateUser(profile: {
  googleId: string;
  email: string | null;
  firstName: string | null;
  lastName: string | null;
  profileImageUrl: string | null;
}): Promise<Express.User> {
  if (isNoDbMode || !db) {
    return {
      id: `mock-${profile.googleId}`,
      email: profile.email,
      firstName: profile.firstName,
      lastName: profile.lastName,
      profileImageUrl: profile.profileImageUrl,
      isPremium: false,
    };
  }

  const existingUsers = await db
    .select()
    .from(users)
    .where(eq(users.googleId, profile.googleId))
    .limit(1);

  if (existingUsers.length > 0) {
    const user = existingUsers[0];
    await db
      .update(users)
      .set({
        email: profile.email,
        firstName: profile.firstName,
        lastName: profile.lastName,
        profileImageUrl: profile.profileImageUrl,
        updatedAt: new Date(),
      })
      .where(eq(users.id, user.id));

    return {
      id: user.id,
      email: profile.email,
      firstName: profile.firstName,
      lastName: profile.lastName,
      profileImageUrl: profile.profileImageUrl,
      isPremium: user.isPremium,
    };
  }

  const newUsers = await db
    .insert(users)
    .values({
      provider: "google",
      providerUserId: profile.googleId,
      googleId: profile.googleId,
      email: profile.email,
      firstName: profile.firstName,
      lastName: profile.lastName,
      profileImageUrl: profile.profileImageUrl,
      isPremium: false,
    })
    .returning();

  const newUser = newUsers[0];
  return {
    id: newUser.id,
    email: newUser.email,
    firstName: newUser.firstName,
    lastName: newUser.lastName,
    profileImageUrl: newUser.profileImageUrl,
    isPremium: newUser.isPremium,
  };
}

export function setupGoogleAuth(app: Express): void {
  const clientId = process.env.GOOGLE_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
  const redirectUri = process.env.GOOGLE_REDIRECT_URI;

  if (!clientId || !clientSecret) {
    console.warn("[AUTH] Google OAuth not configured - missing GOOGLE_CLIENT_ID or GOOGLE_CLIENT_SECRET");
  }

  app.set("trust proxy", 1);

  const sessionTtl = 7 * 24 * 60 * 60 * 1000;

  let sessionStore: session.Store;

  if (isNoDbMode || !process.env.DATABASE_URL) {
    const MemStore = MemoryStore(session);
    sessionStore = new MemStore({
      checkPeriod: sessionTtl,
    });
    console.log("[AUTH] Using memory session store (NO-DB mode)");
  } else {
    const pgStore = connectPg(session);
    sessionStore = new pgStore({
      conString: process.env.DATABASE_URL,
      createTableIfMissing: false,
      ttl: sessionTtl,
      tableName: "sessions",
    });
  }

  const isProduction = process.env.NODE_ENV === "production";

  const sessionCookieConfig = {
    httpOnly: true,
    secure: true,
    sameSite: "none" as const,
    maxAge: sessionTtl,
    path: "/",
    domain: isProduction ? ".switchcontrol.org" : undefined,
  };
  console.log('[AUTH] ===== SESSION COOKIE CONFIG =====');
  console.log('[AUTH] production:', isProduction);
  console.log('[AUTH] cookie:', JSON.stringify(sessionCookieConfig));
  console.log('[AUTH] ================================');

  app.use(
    session({
      secret: process.env.SESSION_SECRET || "switchcontrol-session-secret",
      store: sessionStore,
      resave: false,
      saveUninitialized: false,
      name: "switchcontrol.sid",
      cookie: sessionCookieConfig,
    })
  );

  app.use(passport.initialize());
  app.use(passport.session());

  passport.serializeUser((user: Express.User, done) => {
    done(null, user.id);
  });

  passport.deserializeUser(async (id: string, done) => {
    if (isNoDbMode || !db) {
      return done(null, {
        id,
        email: null,
        firstName: null,
        lastName: null,
        profileImageUrl: null,
        isPremium: false,
      });
    }

    try {
      const userRows = await db
        .select()
        .from(users)
        .where(eq(users.id, id))
        .limit(1);

      if (userRows.length === 0) {
        return done(null, false);
      }

      const user = userRows[0];
      done(null, {
        id: user.id,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        profileImageUrl: user.profileImageUrl,
        isPremium: user.isPremium,
      });
    } catch (error) {
      done(error, null);
    }
  });

  if (clientId && clientSecret) {
    const isProduction = process.env.NODE_ENV === "production";
    const productionDomain = "https://switchcontrol.org";

    let callbackURL: string;
    if (redirectUri && redirectUri.startsWith("http")) {
      callbackURL = redirectUri;
    } else if (isProduction) {
      callbackURL = `${productionDomain}/api/auth/google/callback`;
    } else {
      callbackURL = "/api/auth/google/callback";
    }

    console.log("[AUTH] Google OAuth callback URL:", callbackURL);

    passport.use(
      new GoogleStrategy(
        {
          clientID: clientId,
          clientSecret: clientSecret,
          callbackURL: callbackURL,
          scope: ["profile", "email"],
        },
        async (accessToken, refreshToken, profile, done) => {
          try {
            const email = profile.emails?.[0]?.value || null;
            const user = await findOrCreateUser({
              googleId: profile.id,
              email,
              firstName: profile.name?.givenName || null,
              lastName: profile.name?.familyName || null,
              profileImageUrl: profile.photos?.[0]?.value || null,
            });
            done(null, user);
          } catch (error) {
            done(error as Error, undefined);
          }
        }
      )
    );
  }

  // OAuth success page for Electron - shows message and tries to close tab
  app.get("/auth/success", (req, res) => {
    const token = req.query.token as string;
    const provider = req.query.provider as string || 'google';

    if (!token) {
      return res.status(400).send("Missing authentication token");
    }

    const deepLink = `switchcontrol://auth/success?token=${encodeURIComponent(token)}&provider=${provider}`;

    res.send(`
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>Login Successful - SwitchControl</title>
        <link rel="icon" href="/favicon.ico">
