@import "tailwindcss";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --color-background: hsl(var(--background));
  --color-foreground: hsl(var(--foreground));

  --color-card: hsl(var(--card));
  --color-card-foreground: hsl(var(--card-foreground));

  --color-popover: hsl(var(--popover));
  --color-popover-foreground: hsl(var(--popover-foreground));

  --color-primary: hsl(var(--primary));
  --color-primary-foreground: hsl(var(--primary-foreground));

  --color-secondary: hsl(var(--secondary));
  --color-secondary-foreground: hsl(var(--secondary-foreground));

  --color-muted: hsl(var(--muted));
  --color-muted-foreground: hsl(var(--muted-foreground));

  --color-accent: hsl(var(--accent));
  --color-accent-foreground: hsl(var(--accent-foreground));

  --color-destructive: hsl(var(--destructive));
  --color-destructive-foreground: hsl(var(--destructive-foreground));

  --color-border: hsl(var(--border));
  --color-input: hsl(var(--input));
  --color-ring: hsl(var(--ring));

  --color-chart-1: hsl(var(--chart-1));
  --color-chart-2: hsl(var(--chart-2));
  --color-chart-3: hsl(var(--chart-3));
  --color-chart-4: hsl(var(--chart-4));
  --color-chart-5: hsl(var(--chart-5));

  --color-sidebar: hsl(var(--sidebar));
  --color-sidebar-foreground: hsl(var(--sidebar-foreground));
  --color-sidebar-primary: hsl(var(--sidebar-primary));
  --color-sidebar-primary-foreground: hsl(var(--sidebar-primary-foreground));
  --color-sidebar-accent: hsl(var(--sidebar-accent));
  --color-sidebar-accent-foreground: hsl(var(--sidebar-accent-foreground));
  --color-sidebar-border: hsl(var(--sidebar-border));
  --color-sidebar-ring: hsl(var(--sidebar-ring));

  --font-sans: 'Inter', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  --animate-in: animate-in 0.2s ease-out;
  --animate-out: animate-out 0.2s ease-in;
}

/* Force Dark Mode */
:root {
  color-scheme: dark;

  /* Deep dark background with purple undertone */
  --background: 260 20% 6%;
  --foreground: 210 20% 98%;

  /* Cards with subtle purple tint */
  --card: 260 18% 10%;
  --card-foreground: 210 20% 98%;

  /* Popovers */
  --popover: 260 18% 10%;
  --popover-foreground: 210 20% 98%;

  /* Primary: Purple - Brand identity, premium, intelligence */
  --primary: 270 60% 55%;
  --primary-foreground: 210 20% 98%;

  /* Secondary: Cyan - Performance, speed, interaction */
  --secondary: 190 90% 50%;
  --secondary-foreground: 220 15% 6%;

  /* Muted */
  --muted: 260 15% 20%;
  --muted-foreground: 215 20% 65%;

  /* Accent: Cyan for interactive elements */
  --accent: 190 90% 50%;
  --accent-foreground: 220 15% 6%;

  /* Destructive */
  --destructive: 0 62% 30%;
  --destructive-foreground: 210 20% 98%;

  /* Borders with purple tint */
  --border: 260 15% 18%;
  --input: 260 15% 18%;
  --ring: 270 60% 55%;

  /* Charts - performance metrics use cyan */
  --chart-1: 190 90% 50%;
  --chart-2: 185 80% 45%;
  --chart-3: 200 85% 55%;
  --chart-4: 270 60% 55%;
  --chart-5: 43 74% 66%;

  /* Sidebar with purple */
  --sidebar: 260 20% 8%;
  --sidebar-foreground: 240 5% 96%;
  --sidebar-primary: 270 60% 55%;
  --sidebar-primary-foreground: 210 20% 98%;
  --sidebar-accent: 260 15% 18%;
  --sidebar-accent-foreground: 240 5% 96%;
  --sidebar-border: 260 15% 18%;
  --sidebar-ring: 270 60% 55%;

  /* Brand purple - primary brand color everywhere */
  --brand-purple: 270 60% 55%;
  --brand-purple-light: 270 65% 65%;
  --brand-purple-dark: 270 55% 45%;
  --brand-purple-glow: 270 70% 60%;

  /* Cyan accent - for CTAs and performance only */
  --cyan-accent: 190 90% 50%;
  --cyan-accent-light: 185 85% 60%;
  --cyan-accent-dark: 190 85% 40%;

  /* Structural color - hierarchy, clarity, trust */
  /* #E6EAF0 = hsl(216 25% 92%) */
  --structural: 216 25% 92%;
  --structural-dim: 216 20% 75%;

  --radius: 0.75rem;
}

body {
  @apply font-sans antialiased bg-background text-foreground;
  background-attachment: fixed;
  position: relative;
  overflow-x: hidden;
}

/* Remove focus outlines for mouse/touch users - only show for keyboard */
*:focus {
  outline: none;
}

*:focus-visible {
  outline: 2px solid hsl(var(--ring));
  outline-offset: 2px;
}

/* Animated background container */
.animated-bg {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

/* Slow-moving gradient blobs - Purple dominant */
.bg-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.4;
  will-change: transform;
}

.bg-blob-1 {
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, hsl(270 60% 55% / 0.2), transparent 70%);
  top: -200px;
  left: 30%;
  animation: blobDrift1 15s ease-in-out infinite;
}

.bg-blob-2 {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, hsl(280 55% 50% / 0.15), transparent 70%);
  top: 40%;
  right: -150px;
  animation: blobDrift2 18s ease-in-out infinite;
}

.bg-blob-3 {
  width: 450px;
  height: 450px;
  background: radial-gradient(circle, hsl(260 50% 45% / 0.12), transparent 70%);
  bottom: 10%;
  left: -100px;
  animation: blobDrift3 20s ease-in-out infinite;
}

@keyframes blobDrift1 {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  33% { transform: translate3d(30px, 20px, 0) scale(1.05); }
  66% { transform: translate3d(-20px, -10px, 0) scale(0.95); }
}

@keyframes blobDrift2 {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  50% { transform: translate3d(-40px, 30px, 0) scale(1.08); }
}

@keyframes blobDrift3 {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  40% { transform: translate3d(25px, -20px, 0) scale(1.03); }
  80% { transform: translate3d(-15px, 15px, 0) scale(0.97); }
}

/* Structural color utilities */
.text-structural {
  color: hsl(var(--structural));
}

.text-structural-dim {
  color: hsl(var(--structural-dim));
}

.border-structural {
  border-color: hsl(var(--structural) / 0.12);
}

.bg-structural-overlay {
  background-color: hsl(var(--structural) / 0.04);
}

/* Divider with structural color */
.divider-structural {
  height: 1px;
  background: linear-gradient(90deg, transparent, hsl(var(--structural) / 0.15), transparent);
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  @apply bg-transparent;
}
::-webkit-scrollbar-thumb {
  @apply bg-muted rounded-full;
}
::-webkit-scrollbar-thumb:hover {
  @apply bg-muted-foreground/50;
}

/* Utility classes for data text */
.font-data {
  @apply font-mono tracking-tight;
}

/* Custom Animations */
@keyframes glow-pulse {
  0% { box-shadow: 0 0 5px hsl(var(--primary) / 0.3); }
  50% { box-shadow: 0 0 25px hsl(var(--primary) / 0.6), 0 0 40px hsl(var(--primary) / 0.2); }
  100% { box-shadow: 0 0 5px hsl(var(--primary) / 0.3); }
}

.animate-glow {
  animation: glow-pulse 3s infinite;
}

/* Purple brand glow - ambient, slow, everywhere */
@keyframes purple-glow {
  0% { box-shadow: 0 0 5px hsl(270 60% 55% / 0.3); }
  50% { box-shadow: 0 0 25px hsl(270 60% 55% / 0.5), 0 0 40px hsl(270 60% 55% / 0.2); }
  100% { box-shadow: 0 0 5px hsl(270 60% 55% / 0.3); }
}

.animate-purple-glow {
  animation: purple-glow 4s ease-in-out infinite;
}

/* Cyan glow for interactive elements - reactive, fast */
@keyframes cyan-glow {
  0% { box-shadow: 0 0 5px hsl(190 90% 50% / 0.3); }
  50% { box-shadow: 0 0 20px hsl(190 90% 50% / 0.5), 0 0 35px hsl(190 90% 50% / 0.2); }
  100% { box-shadow: 0 0 5px hsl(190 90% 50% / 0.3); }
}

.animate-cyan-glow {
  animation: cyan-glow 2s ease-in-out infinite;
}

/* Purple ambient pulse - slow background effect */
@keyframes purple-ambient {
  0%, 100% { 
    opacity: 0.4;
    transform: scale(1);
  }
  50% { 
    opacity: 0.6;
    transform: scale(1.05);
  }
}

.animate-purple-ambient {
  animation: purple-ambient 6s ease-in-out infinite;
}

/* Noise overlay */
.bg-noise {
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.05'/%3E%3C/svg%3E");
  pointer-events: none;
}

/* Drifting blob animations */

/* Wave contour line animations - GPU optimized */
@keyframes waveMove1 {
  0%, 100% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(30px, 8px, 0); }
  50% { transform: translate3d(0, 0, 0); }
  75% { transform: translate3d(-30px, -8px, 0); }
}

@keyframes waveMove2 {
  0%, 100% { transform: translate3d(0, 0, 0); }
  33% { transform: translate3d(-25px, 6px, 0); }
  66% { transform: translate3d(25px, -6px, 0); }
}

@keyframes waveMove3 {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(20px, 5px, 0); }
}

.animate-wave-1 {
  animation: waveMove1 14s ease-in-out infinite;
  will-change: transform;
}

.animate-wave-2 {
  animation: waveMove2 18s ease-in-out infinite;
  animation-delay: 0.5s;
  will-change: transform;
}

.animate-wave-3 {
  animation: waveMove3 22s ease-in-out infinite;
  animation-delay: 1s;
  will-change: transform;
}

/* Slow pulse for center glow */
@keyframes pulseSlow {
  0%, 100% { 
    transform: scale(1);
    opacity: 0.3;
  }
  50% { 
    transform: scale(1.08);
    opacity: 0.45;
  }
}

.animate-pulse-slow {
  animation: pulseSlow 6s ease-in-out infinite;
  will-change: transform, opacity;
}

@keyframes blobFloat1 {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  25% { transform: translate3d(20px, -15px, 0) scale(1.03); }
  50% { transform: translate3d(-15px, 20px, 0) scale(0.97); }
  75% { transform: translate3d(-20px, -10px, 0) scale(1.01); }
}

@keyframes blobFloat2 {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  33% { transform: translate3d(-25px, 15px, 0) scale(1.02); }
  66% { transform: translate3d(15px, -20px, 0) scale(0.98); }
}

@keyframes blobFloat3 {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  50% { transform: translate3d(15px, 15px, 0) scale(1.02); }
}

@keyframes gradientShift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes borderGlow {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

@keyframes ctaPulse {
  0%, 100% { 
    box-shadow: 0 0 20px hsl(190 90% 50% / 0.4), 
                0 4px 20px hsl(190 90% 50% / 0.3);
  }
  50% { 
    box-shadow: 0 0 35px hsl(190 90% 50% / 0.6), 
                0 4px 35px hsl(190 90% 50% / 0.4);
  }
}

@keyframes heroFloat {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(0, -8px, 0); }
}

@keyframes heroFloatSlow {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(0, -5px, 0); }
}

@keyframes pillFloat {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(0, -4px, 0); }
}

.animate-hero-float {
  animation: heroFloat 6s ease-in-out infinite;
  will-change: transform;
}

.animate-hero-float-slow {
  animation: heroFloatSlow 7s ease-in-out infinite;
  animation-delay: 0.3s;
  will-change: transform;
}

.animate-pill-float {
  animation: pillFloat 5s ease-in-out infinite;
  will-change: transform;
}

@media (prefers-reduced-motion: reduce) {
  .animate-hero-float,
  .animate-hero-float-slow,
  .animate-pill-float {
    animation-duration: 12s;
  }
}

.animate-blob-1 {
  animation: blobFloat1 25s ease-in-out infinite;
}

.animate-blob-2 {
  animation: blobFloat2 30s ease-in-out infinite;
}

.animate-blob-3 {
  animation: blobFloat3 20s ease-in-out infinite;
}

/* Contour parallax animations - slow drifting motion */
@keyframes contourDrift1 {
  0%, 100% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(40px, 8px, 0); }
  50% { transform: translate3d(10px, -5px, 0); }
  75% { transform: translate3d(-30px, 10px, 0); }
}

@keyframes contourDrift2 {
  0%, 100% { transform: translate3d(0, 0, 0); }
  33% { transform: translate3d(-35px, 12px, 0); }
  66% { transform: translate3d(45px, -8px, 0); }
}

@keyframes contourDrift3 {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(25px, 6px, 0); }
}

@keyframes contourDrift4 {
  0%, 100% { transform: translate3d(0, 0, 0); }
  40% { transform: translate3d(-20px, -10px, 0); }
  80% { transform: translate3d(30px, 5px, 0); }
}

.animate-contour-1 {
  animation: contourDrift1 20s ease-in-out infinite;
  will-change: transform;
}

.animate-contour-2 {
  animation: contourDrift2 25s ease-in-out infinite;
  animation-delay: 2s;
  will-change: transform;
}

.animate-contour-3 {
  animation: contourDrift3 18s ease-in-out infinite;
  animation-delay: 4s;
  will-change: transform;
}

.animate-contour-4 {
  animation: contourDrift4 22s ease-in-out infinite;
  animation-delay: 1s;
  will-change: transform;
}

/* App background scan lines - vertical rain effect */
@keyframes scanlineFall {
  0% { transform: translateY(-100%); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateY(250%); opacity: 0; }
}

.app-scanline-fall {
  animation: scanlineFall 6s linear infinite;
  will-change: transform;
}

/* Grid overlay subtle breathing */
@keyframes gridBreathe {
  0%, 100% { opacity: 0.9; }
  50% { opacity: 1.1; }
}

.app-grid-overlay {
  animation: gridBreathe 8s ease-in-out infinite;
}

.app-grid-overlay-fine {
  animation: gridBreathe 12s ease-in-out infinite;
  animation-delay: 3s;
}

/* Pulsing center vignette */
@keyframes pulseVignette {
  0%, 100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.05); }
}

.app-pulse-vignette {
  animation: pulseVignette 6s ease-in-out infinite;
}

/* Animated gradient mesh - slow ambient motion */
@keyframes meshGradientShift {
  0%, 100% { background-position: 0% 0%; }
  25% { background-position: 100% 50%; }
  50% { background-position: 50% 100%; }
  75% { background-position: 0% 50%; }
}

.animate-gradient-mesh {
  background: 
    radial-gradient(ellipse 60% 50% at 20% 30%, hsl(270 60% 55% / 0.08) 0%, transparent 50%),
    radial-gradient(ellipse 50% 60% at 80% 70%, hsl(190 90% 50% / 0.05) 0%, transparent 50%),
    radial-gradient(ellipse 70% 40% at 50% 50%, hsl(280 55% 50% / 0.06) 0%, transparent 50%);
  background-size: 200% 200%;
  animation: meshGradientShift 10s ease-in-out infinite;
  will-change: background-position;
}

@media (max-width: 768px) {
  .animate-gradient-mesh {
    animation-duration: 30s;
    background:
      radial-gradient(ellipse 80% 60% at 30% 30%, hsl(270 60% 55% / 0.06) 0%, transparent 50%),
      radial-gradient(ellipse 60% 70% at 70% 70%, hsl(190 90% 50% / 0.04) 0%, transparent 50%);
    background-size: 200% 200%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .animate-gradient-mesh {
    animation: none;
  }
}

/* Particle floating animation */
@keyframes particleFloat {
  0% {
    transform: translate3d(0, 0, 0);
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  50% {
    transform: translate3d(var(--drift-x, 10px), -30px, 0);
  }
  90% {
    opacity: 1;
  }
  100% {
    transform: translate3d(calc(var(--drift-x, 10px) * -0.5), 30px, 0);
    opacity: 0;
  }
}

@keyframes particleTwinkle {
  0%, 100% { opacity: 0.15; }
  50% { opacity: 0.4; }
}

.animate-particle {
  animation: 
    particleFloat var(--particle-speed, 20s) ease-in-out infinite,
    particleTwinkle 4s ease-in-out infinite;
  will-change: transform, opacity;
}

/* Logo float animation - subtle and premium */
@keyframes logoFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

@keyframes logoShine {
  0% { transform: translateX(-100%) skewX(-12deg); }
  100% { transform: translateX(200%) skewX(-12deg); }
}

.animate-logo-float {
  animation: logoFloat 4s ease-in-out infinite;
  will-change: transform;
}

.animate-logo-shine {
  animation: logoShine 4s ease-in-out infinite;
  animation-delay: 1s;
}

.animate-gradient-shift {
  background-size: 200% 200%;
  animation: gradientShift 8s ease infinite;
}

.animate-shimmer {
  background: linear-gradient(
    90deg,
    transparent 0%,
    hsl(190 90% 50% / 0.1) 50%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: shimmer 2s ease-out forwards;
}

.animate-cta-pulse {
  animation: ctaPulse 3s ease-in-out infinite;
}

/* Animated border gradient */
.animated-border {
  position: relative;
}

.animated-border::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    hsl(190 90% 50% / 0.5),
    hsl(185 80% 60% / 0.5),
    transparent
  );
  background-size: 300% 100%;
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.animated-border:hover::before {
  opacity: 1;
  animation: gradientShift 3s linear infinite;
}

/* Scroll blur reveal system */
[data-reveal] {
  opacity: 0;
  transform: translate3d(0, 18px, 0);
  filter: blur(10px);
  transition: opacity 700ms ease, transform 700ms ease, filter 700ms ease;
  will-change: opacity, transform, filter;
}

[data-reveal].is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  filter: blur(0px);
}

[data-reveal][data-delay="1"] { transition-delay: 60ms; }
[data-reveal][data-delay="2"] { transition-delay: 120ms; }
[data-reveal][data-delay="3"] { transition-delay: 180ms; }
[data-reveal][data-delay="4"] { transition-delay: 240ms; }

@media (max-width: 768px) {
  [data-reveal] {
    filter: blur(6px);
    transform: translate3d(0, 12px, 0);
    transition-duration: 600ms;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-reveal] {
    transition: none;
    opacity: 1;
    transform: none;
    filter: none;
  }
}

/* AnimateIn component blur reveal */
.animate-in-wrapper {
  opacity: 0;
  transform: translate3d(0, 18px, 0);
  filter: blur(10px);
  transition: opacity 700ms ease, transform 700ms ease, filter 700ms ease;
  will-change: opacity, transform, filter;
}

.animate-in-wrapper.animate-in-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  filter: blur(0px);
}

@media (max-width: 768px) {
  .animate-in-wrapper {
    filter: blur(6px);
    transform: translate3d(0, 12px, 0);
    transition-duration: 600ms;
  }
}

@media (prefers-reduced-motion: reduce) {
  .animate-in-wrapper {
    transition: none;
    opacity: 1;
    transform: none;
    filter: none;
  }
}

/* Page enter animation */
.page-enter {
  opacity: 0;
  transform: translateY(10px);
  animation: pageEnter 450ms ease forwards;
}

@keyframes pageEnter {
  to { opacity: 1; transform: translateY(0); }
}

/* Interactive button glow effect */
@keyframes buttonShine {
  0% { transform: translateX(-100%) rotate(45deg); }
  100% { transform: translateX(200%) rotate(45deg); }
}

.btn-shine {
  position: relative;
  overflow: hidden;
}

.btn-shine::after {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 50%;
  height: 200%;
  background: linear-gradient(
    to right,
    transparent 0%,
    rgba(255, 255, 255, 0.1) 50%,
    transparent 100%
  );
  transform: translateX(-100%) rotate(45deg);
}

.btn-shine:hover::after {
  animation: buttonShine 0.6s ease forwards;
}

/* Glassmorphism card style */
.glass-card {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.glass-card:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: hsl(190 90% 50% / 0.4);
  box-shadow: 0 0 25px hsl(190 90% 50% / 0.12);
  transform: translateY(-2px);
}

/* Card hover with subtle cyan glow */
.card-hover-glow {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.card-hover-glow:hover {
  border-color: hsl(190 90% 50% / 0.3);
  box-shadow: 0 4px 20px hsl(190 90% 50% / 0.1), 0 0 0 1px hsl(190 90% 50% / 0.1);
  transform: translateY(-2px);
}

/* Structural border for cards */
.border-structural-subtle {
  border-color: hsl(var(--structural) / 0.1);
}

/* Section heading style with structural color */
.section-heading {
  color: hsl(var(--structural));
  font-weight: 600;
  letter-spacing: -0.01em;
}

.section-subtitle {
  color: hsl(var(--structural-dim));
  font-weight: 400;
}

/* Neon glow text - Cyan */
.neon-text {
  text-shadow: 
    0 0 5px hsl(190 90% 50% / 0.5),
    0 0 10px hsl(190 90% 50% / 0.3),
    0 0 20px hsl(190 90% 50% / 0.2);
}

/* AI neon text - Purple for AI features */
.neon-text-ai {
  text-shadow: 
    0 0 5px hsl(270 60% 55% / 0.5),
    0 0 10px hsl(270 60% 55% / 0.3),
    0 0 20px hsl(270 60% 55% / 0.2);
}

/* Premium gradient text - Cyan to lighter cyan */
.gradient-text {
  background: linear-gradient(135deg, hsl(190 90% 50%), hsl(185 80% 60%));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* AI gradient text - Purple gradient */
.gradient-text-ai {
  background: linear-gradient(135deg, hsl(270 60% 55%), hsl(280 70% 65%));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Floating animation for cards */
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.animate-float {
  animation: float 4s ease-in-out infinite;
}

/* Pulsing ring animation - Cyan */
@keyframes pulseRing {
  0% { 
    box-shadow: 0 0 0 0 hsl(190 90% 50% / 0.4);
  }
  70% { 
    box-shadow: 0 0 0 10px hsl(190 90% 50% / 0);
  }
  100% { 
    box-shadow: 0 0 0 0 hsl(190 90% 50% / 0);
  }
}

.pulse-ring {
  animation: pulseRing 2s infinite;
}

/* AI pulse ring - Purple */
@keyframes pulseRingAI {
  0% { 
    box-shadow: 0 0 0 0 hsl(270 60% 55% / 0.4);
  }
  70% { 
    box-shadow: 0 0 0 10px hsl(270 60% 55% / 0);
  }
  100% { 
    box-shadow: 0 0 0 0 hsl(270 60% 55% / 0);
  }
}

.pulse-ring-ai {
  animation: pulseRingAI 2s infinite;
}

/* Premium card with 3D tilt effect */
.tilt-card {
  transform-style: preserve-3d;
  transition: transform 0.3s ease;
}

.tilt-card:hover {
  transform: perspective(1000px) rotateX(2deg) rotateY(-2deg) translateY(-4px);
}

/* Premium button styles */
.premium-btn {
  position: relative;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.premium-btn::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
  transform: translateX(-100%);
  transition: transform 0.5s ease;
}

.premium-btn:hover::before {
  transform: translateX(100%);
}

.premium-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 40px -10px hsl(190 90% 50% / 0.5);
}

.premium-btn:active {
  transform: translateY(0) scale(0.98);
}

/* Icon hover animation */
.icon-hover {
  transition: all 0.3s ease;
}

.icon-hover:hover {
  transform: scale(1.1) rotate(5deg);
  filter: drop-shadow(0 0 8px hsl(190 90% 50% / 0.5));
}

/* Reduce motion preferences - REDUCE animations, don't eliminate them */
@media (prefers-reduced-motion: reduce) {
  .animate-blob-1,
  .animate-blob-2,
  .animate-blob-3 {
    animation-duration: 60s;
  }

  .animate-wave-1,
  .animate-wave-2,
  .animate-wave-3 {
    animation-duration: 40s;
  }

  .animate-particle {
    animation-duration: 40s;
  }

  .animate-contour-1,
  .animate-contour-2,
  .animate-contour-3,
  .animate-contour-4 {
    animation-duration: 50s;
  }

  .app-scanline-fall {
    animation: none;
  }

  .app-grid-overlay,
  .app-grid-overlay-fine {
    animation: none;
  }

  .app-pulse-vignette {
    animation: none;
  }

  .animate-pulse-slow {
    animation-duration: 12s;
  }

  .animate-gradient-shift {
    animation-duration: 20s;
  }

  .animate-cta-pulse,
  .animate-hero-float,
  .animate-float,
  .pulse-ring {
    animation-duration: 6s;
  }

  .animate-logo-float {
    animation-duration: 8s;
  }

  .animate-logo-shine {
    animation-duration: 8s;
  }

  .animate-shimmer {
    animation: none;
  }

  .btn-shine::after,
  .premium-btn::before {
    animation-duration: 1s;
  }

  .tilt-card:hover {
    transform: translateY(-2px);
  }

  .premium-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 5px 20px -5px hsl(190 90% 50% / 0.3);
  }

  .icon-hover:hover {
    transform: scale(1.05);
  }

  .animated-border::before {
    animation-duration: 6s;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .page-enter {
    opacity: 1;
    transform: none;
    animation: none;
  }
}

/* Electron App Structure - CRITICAL for frameless window */
.app-root {
  width: 100%;
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: hsl(var(--background));
  overflow: hidden;
}

.titlebar {
  height: 32px;
  min-height: 32px;
  -webkit-app-region: drag;
  flex-shrink: 0;
  z-index: 9999;
  position: relative;
}

/* Window control buttons inside titlebar must NOT be draggable */
.titlebar-controls {
  -webkit-app-region: no-drag;
}

.app-content {
  flex: 1;
  height: calc(100vh - 32px);
  overflow: auto;
  position: relative;
}

/* Animated contour keyframes for Splash screen */
@keyframes contourMove1 {
  0% { transform: translate(0, 0); }
  50% { transform: translate(50px, 25px); }
  100% { transform: translate(0, 0); }
}

@keyframes contourMove2 {
  0% { transform: translate(0, 0); }
  50% { transform: translate(-40px, 20px); }
  100% { transform: translate(0, 0); }
}

@keyframes contourMove3 {
  0% { transform: translate(0, 0); }
  33% { transform: translate(30px, -15px); }
  66% { transform: translate(-20px, 30px); }
  100% { transform: translate(0, 0); }
}

.animate-contour-move-1 {
  animation: contourMove1 12s ease-in-out infinite;
  will-change: transform;
}

.animate-contour-move-2 {
  animation: contourMove2 15s ease-in-out infinite;
  animation-delay: -3s;
  will-change: transform;
}

.animate-contour-move-3 {
  animation: contourMove3 18s ease-in-out infinite;
  animation-delay: -6s;
  will-change: transform;
}

/* Splash screen contour animations - slow drift */
@keyframes splashContourDrift1 {
  0% { transform: translate(0, 0); }
  33% { transform: translate(60px, 30px); }
  66% { transform: translate(-30px, 15px); }
  100% { transform: translate(0, 0); }
}

@keyframes splashContourDrift2 {
  0% { transform: translate(0, 0); }
  50% { transform: translate(-50px, 25px); }
  100% { transform: translate(0, 0); }
}

.splash-contour-drift-1 {
  animation: splashContourDrift1 25s ease-in-out infinite;
  will-change: transform;
}

.splash-contour-drift-2 {
  animation: splashContourDrift2 30s ease-in-out infinite;
  animation-delay: -8s;
  will-change: transform;
}

/* Login screen contour animation */
@keyframes loginContourDrift {
  0% { transform: translate(0, 0); }
  50% { transform: translate(40px, 20px); }
  100% { transform: translate(0, 0); }
}

.login-contour-drift {
  animation: loginContourDrift 20s ease-in-out infinite;
  will-change: transform;
}

