interface RevealProps {
  children: ReactNode;
  className?: string;
  delay?: number;
  duration?: number;
  direction?: 'up' | 'down' | 'left' | 'right';
  distance?: number;
}

export function Reveal({ 
  children, 
  className,
  delay = 0,
  duration = 0.5,
  direction = 'up',
  distance = 24
}: RevealProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [isVisible, setIsVisible] = useState(false);
  const { prefersReducedMotion } = useMotion();
  const hasChecked = useRef(false);

  useEffect(() => {
    if (hasChecked.current) return;
    hasChecked.current = true;

    const el = ref.current;
    if (!el) {
      setIsVisible(true);
      return;
    }

    // CRITICAL FIX: Check if element is already in viewport on mount
    const rect = el.getBoundingClientRect();
    const inViewport = (
      rect.top < window.innerHeight &&
      rect.bottom > 0
    );

    if (inViewport) {
      // Already visible, animate in
      setIsVisible(true);
      return;
    }

    // Use IntersectionObserver for scroll reveal
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { 
        threshold: 0.05, 
        rootMargin: "50px 0px 0px 0px"
      }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // When reduced motion is preferred, show content immediately without animation
  if (prefersReducedMotion) {
    return (
      <div ref={ref} className={cn(className)}>
        {children}
      </div>
    );
  }

  const getTransform = () => {
    if (isVisible) return 'translate(0, 0)';
    switch (direction) {
      case 'up': return `translateY(${distance}px)`;
      case 'down': return `translateY(-${distance}px)`;
      case 'left': return `translateX(${distance}px)`;
      case 'right': return `translateX(-${distance}px)`;
      default: return `translateY(${distance}px)`;
    }
  };

  return (
    <div
      ref={ref}
      className={cn(className)}
      style={{
        opacity: isVisible ? 1 : 0,
        transform: getTransform(),
        transition: `opacity ${duration}s ease-out ${delay}s, transform ${duration}s ease-out ${delay}s`,
        willChange: 'opacity, transform',
      }}
    >
      {children}
    </div>
  );
}

export { motion, AnimatePresence };

