const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const binDir = path.join(__dirname, '..', 'bin');
const exePath = path.join(binDir, 'sc_memory.exe');
const nativeDir = path.join(__dirname, '..', 'native', 'sc_memory');
const releaseExe = path.join(nativeDir, 'target', 'release', 'sc_memory.exe');

function hasCargo() {
  try {
    execSync('cargo --version', { stdio: 'ignore', windowsHide: true });
    return true;
  } catch {
    return false;
  }
}

if (!fs.existsSync(binDir)) {
  fs.mkdirSync(binDir, { recursive: true });
}

if (hasCargo()) {
  console.log('[build-native] Rust toolchain found — compiling sc_memory...');
  try {
    execSync('cargo build --release', { cwd: nativeDir, stdio: 'inherit', windowsHide: true });
    fs.copyFileSync(releaseExe, exePath);
    console.log('[build-native] sc_memory.exe built and copied to bin/');
  } catch (err) {
    if (fs.existsSync(exePath)) {
      console.warn('[build-native] Cargo build failed but existing bin/sc_memory.exe found — using cached binary.');
    } else {
      console.error('[build-native] ERROR: Cargo build failed and no cached binary exists.');
      console.error('[build-native] Install Rust from https://rustup.rs and try again.');
      process.exit(1);
    }
  }
} else if (fs.existsSync(exePath)) {
  const stats = fs.statSync(exePath);
  const sizeKB = Math.round(stats.size / 1024);
  console.log(`[build-native] Cargo not found — using existing bin/sc_memory.exe (${sizeKB} KB)`);
} else {
  console.error('[build-native] ERROR: Cargo is not installed and no pre-built bin/sc_memory.exe found.');
  console.error('[build-native] Install Rust from https://rustup.rs then run this build again.');
  process.exit(1);
}

client/src/advisor/types.ts.content:
export interface SignalValue {
  value: string | number | boolean | null;
  source: "electron" | "store" | "browser" | "static";
  error?: string;
}

export interface Signals {
  system: Record<string, SignalValue>;
  network: Record<string, SignalValue>;
  app: Record<string, SignalValue>;
}

export type RuleSeverity = "critical" | "recommended" | "informational";
export type FindingStatus = "pass" | "fail" | "unknown";

export interface RuleFix {
  type: "app_tweak";
  tweakId: string;
  enable: boolean;
}

export interface Rule {
  id: string;
  title: string;
  description: string;
  severity: RuleSeverity;
  maxPoints: number;
  signal: string;
  operator: "eq" | "neq" | "gt" | "lt" | "gte" | "lte" | "contains" | "not_contains";
  expected: string | number | boolean;
  failMessage: string;
  passMessage: string;
  fix?: RuleFix;
}

export interface Ruleset {
  version: string;
  rules: Rule[];
}

export interface Finding {
  ruleId: string;
  title: string;
  status: FindingStatus;
  severity: RuleSeverity;
  message: string;
  pointsDeducted: number;
  fix?: RuleFix;
}

export interface SignalsHealth {
  total: number;
  collected: number;
  degraded: boolean;
  errors: string[];
}

export interface AdvisorReport {
  score: number;
  findings: Finding[];
  topFailed: Finding[];
  signalsHealth: SignalsHealth;
  generatedAt: string;
}

